import { useCallback, useMemo, useEffect } from 'react';
import { clientLogger } from '@/lib/clientLogger';
import {
  buildReferenceAliases,
  findExistingReference,
  mergeReference,
} from '@/services/chatReferenceManager';
import {
  createSendMessageOrchestrator,
  type SendMessageRequestOptions,
} from '@/services/createSendMessageOrchestrator';
import { createChatStreamService } from '@/services/chatStreamService';
import { normalizeUserMessageInput } from '@/services/normalizeUserMessageInput';
import { submitQuestionAnswerRequest } from '@/services/submitQuestionAnswer';
import { useConversationLifecycle } from '@/hooks/useConversationLifecycle';
import { useMessageStateHandler } from '@/hooks/useMessageStateHandler';
import { useReferenceManager } from '@/hooks/useReferenceManager';
import { useTodoHandler } from '@/hooks/useTodoHandler';
import { useChatRuntimeStore, type ConversationRuntimeState } from '@/stores/chatRuntimeStore';
import type {
  ChatMessage,
  AgentReferenceMap,
  AskUserAnswerMap,
  UserMessageInput,
} from '@/types/agent';

type SendMessageOptions = SendMessageRequestOptions;

type UseChatApiOptions = {
  onMessageAdded?: (conversationId: number, message: ChatMessage) => void;
  onTitleGenerated?: (conversationId: number, title: string) => void;
};

const LEGACY_REFERENCES_KEY = 'fin-agent-references';
const EMPTY_MESSAGES: ChatMessage[] = [];
const EMPTY_REFERENCES: AgentReferenceMap = {};
const EMPTY_FOLLOWUPS: string[] = [];

/**
 * 聊天运行时主入口 Hook。
 * 负责编排消息发送、流式状态、引用与待办同步，不包含底层实现细节。
 *
 * @param options - 可选回调，用于消息持久化与标题更新等外部副作用。
 * @returns 当前会话状态与聊天操作集合（发送、停止生成、提交澄清回答等）。
 */
export function useChatApi(options?: UseChatApiOptions) {
  const onMessageAdded = options?.onMessageAdded;
  const onTitleGenerated = options?.onTitleGenerated;
  const streamService = useMemo(() => createChatStreamService(), []);
  const activeConversationId = useChatRuntimeStore((state) => state.activeConversationId);
  const messages = useChatRuntimeStore((state) => {
    const activeId = state.activeConversationId;
    if (activeId === undefined) return state.detachedState.messages;
    return state.conversationsById[activeId]?.messages ?? EMPTY_MESSAGES;
  });
  const todoList = useChatRuntimeStore((state) => {
    const activeId = state.activeConversationId;
    if (activeId === undefined) return state.detachedState.todoList;
    return state.conversationsById[activeId]?.todoList ?? null;
  });
  const references = useChatRuntimeStore((state) => {
    const activeId = state.activeConversationId;
    if (activeId === undefined) return state.detachedState.references;
    return state.conversationsById[activeId]?.references ?? EMPTY_REFERENCES;
  });
  const followups = useChatRuntimeStore((state) => {
    const activeId = state.activeConversationId;
    if (activeId === undefined) return state.detachedState.followups;
    return state.conversationsById[activeId]?.followups ?? EMPTY_FOLLOWUPS;
  });
  const isLoading = useChatRuntimeStore((state) => {
    const activeId = state.activeConversationId;
    if (activeId === undefined) return false;
    return (state.loadingCountByConversation[activeId] ?? 0) > 0;
  });

  useEffect(() => {
    return () => {
      streamService.clear();
    };
  }, [streamService]);

  const createId = useCallback(() => `${Date.now()}-${Math.random().toString(16).slice(2, 8)}`, []);

  const ensureConversationState = useCallback(
    (conversationId: number): ConversationRuntimeState => {
      return useChatRuntimeStore.getState().ensureConversationState(conversationId);
    },
    [],
  );

  const {
    saveRefsToStorage,
    deleteRefsFromStorage,
    hydrateReferencesFromStorage,
    mergeReferencesForConversation,
  } = useReferenceManager({
    legacyReferencesKey: LEGACY_REFERENCES_KEY,
  });

  const { updateTodoListForConversation, completeTodosForConversation } = useTodoHandler();
  const {
    mutateConversationMessages,
    upsertFinalMessage,
    pushMessage,
    updateQuestionMessage,
    upsertWidgetMessage,
    finalizeStreamingMessages,
    markStreamingMessageComplete,
    clearAssistantStreamIds,
    setAssistantStreamId,
    attachReferencesToLatestAssistant,
  } = useMessageStateHandler({
    onMessageAdded,
    createId,
    mergeReferencesForConversation,
  });
  const updateFollowupsForConversation = useCallback(
    (conversationId: number, nextFollowups: string[]) => {
      useChatRuntimeStore.getState().updateConversationState(conversationId, (state) => ({
        ...state,
        followups: nextFollowups,
      }));
    },
    [],
  );

  const { setActiveConversation, updateLoadingCounter, loadConversationState, clearMessages } =
    useConversationLifecycle({
      streamService,
      hydrateReferencesFromStorage,
      saveRefsToStorage,
      deleteRefsFromStorage,
      completeTodosForConversation,
    });

  const sendMessageOrchestrator = useMemo(
    () =>
      createSendMessageOrchestrator({
        getRuntimeStore: () => useChatRuntimeStore.getState(),
        streamService,
        createId,
        pushMessage,
        updateLoadingCounter,
        updateFollowupsForConversation,
        clearAssistantStreamIds,
        updateTodoListForConversation,
        mutateConversationMessages,
        setAssistantStreamId,
        finalizeStreamingMessages,
        upsertFinalMessage,
        onTitleGenerated,
        markStreamingMessageComplete,
        ensureConversationState,
        buildReferenceAliases,
        findExistingReference,
        mergeReference,
        attachReferencesToLatestAssistant,
        mergeReferencesForConversation,
        updateQuestionMessage,
        upsertWidgetMessage,
      }),
    [
      attachReferencesToLatestAssistant,
      finalizeStreamingMessages,
      markStreamingMessageComplete,
      mergeReferencesForConversation,
      mutateConversationMessages,
      pushMessage,
      upsertFinalMessage,
      updateLoadingCounter,
      updateFollowupsForConversation,
      updateTodoListForConversation,
      updateQuestionMessage,
      upsertWidgetMessage,
      ensureConversationState,
      createId,
      clearAssistantStreamIds,
      onTitleGenerated,
      setAssistantStreamId,
      streamService,
    ],
  );

  const sendMessage = useCallback(
    async (
      messageInput: UserMessageInput,
      sessionId?: string,
      options?: SendMessageOptions,
    ): Promise<{ sessionId: string; title?: string; aborted?: boolean }> => {
      const normalizedInput = normalizeUserMessageInput(messageInput);
      return sendMessageOrchestrator.sendMessage(normalizedInput, sessionId, options);
    },
    [sendMessageOrchestrator],
  );

  const stopGeneration = useCallback(() => {
    const conversationId = useChatRuntimeStore.getState().activeConversationId;
    if (conversationId === undefined) return;

    const aborted = streamService.abortConversation(conversationId);
    if (aborted.length > 0) {
      aborted.forEach(() => {
        updateLoadingCounter(conversationId, -1);
      });
      finalizeStreamingMessages(conversationId);
    }
  }, [finalizeStreamingMessages, streamService, updateLoadingCounter]);

  const submitQuestionAnswer = useCallback(
    async (requestId: string, answers: AskUserAnswerMap) => {
      const conversationId = useChatRuntimeStore.getState().activeConversationId;
      if (conversationId === undefined) {
        throw new Error('没有选中的会话');
      }
      if (!requestId) return;

      updateQuestionMessage(conversationId, requestId, (msg) => ({
        ...msg,
        questionStatus: 'answered',
        questionAnswers: answers,
        questionError: undefined,
      }));

      try {
        await submitQuestionAnswerRequest({
          requestId,
          answers,
          conversationId,
        });
      } catch (error) {
        clientLogger.errorWithCause('chat.answer_submit_failed', error, {
          phase: 'submitQuestionAnswer',
          conversationId,
          requestId,
        });
        updateQuestionMessage(conversationId, requestId, (msg) => ({
          ...msg,
          questionStatus: 'error',
          questionError: error instanceof Error ? error.message : '提交回答失败，请稍后重试',
          questionAnswers: answers,
        }));
        throw error;
      }
    },
    [updateQuestionMessage],
  );

  return {
    activeConversationId,
    messages,
    todoList,
    references,
    followups,
    isLoading,
    sendMessage,
    stopGeneration,
    submitQuestionAnswer,
    clearMessages,
    loadConversationState,

