import { create } from 'zustand';

import type { AgentReferenceMap, AgentTodoList, ChatMessage } from '@/types/agent';

export type ConversationRuntimeState = {
  messages: ChatMessage[];
  todoList: AgentTodoList | null;
  references: AgentReferenceMap;
  followups: string[];
};

export type StreamMessageIds = Partial<Record<'thinking' | 'text', ChatMessage['id']>>;

type ChatRuntimeStoreState = {
  activeConversationId: number | undefined;
  detachedState: ConversationRuntimeState;
  conversationsById: Record<number, ConversationRuntimeState>;
  loadingCountByConversation: Record<number, number>;
  finalMessageIdByConversation: Record<number, ChatMessage['id']>;
  lastAssistantChunkByConversation: Record<number, string>;
  pendingReferencesByConversation: Record<number, AgentReferenceMap>;
  streamMessageIdsByConversation: Record<number, StreamMessageIds>;
  widgetMessageIdsByConversation: Record<number, Record<string, ChatMessage['id']>>;
  completedMessageIdsByConversation: Record<number, Set<string>>;
  referenceWriteQueueByConversation: Record<number, Promise<void>>;
  hasMigratedLegacyRefs: boolean;

  ensureConversationState: (conversationId: number) => ConversationRuntimeState;
  getConversationState: (conversationId: number) => ConversationRuntimeState | undefined;
  setConversationState: (conversationId: number, nextState: ConversationRuntimeState) => void;
  updateConversationState: (
    conversationId: number,
    updater: (state: ConversationRuntimeState) => ConversationRuntimeState,
  ) => ConversationRuntimeState;
  deleteConversationState: (conversationId: number) => void;
  setDetachedState: (nextState: ConversationRuntimeState) => void;
  setActiveConversationId: (conversationId: number | undefined) => void;

  getLoadingCount: (conversationId: number) => number;
  setLoadingCount: (conversationId: number, count: number) => void;
  clearLoadingCount: (conversationId: number) => void;
  clearAllLoadingCounts: () => void;

  getFinalMessageId: (conversationId: number) => ChatMessage['id'] | undefined;
  setFinalMessageId: (conversationId: number, messageId: ChatMessage['id']) => void;
