      }),
      storage: createJSONStorage(() => createIndexedDbStorage()),
    }
  )
);
```

## ChatService 依赖注入（目标）
```typescript
export class ChatService {
  constructor(private store: typeof useChatStore) {}

  private streamControllers = new Map<string, AbortController>();

  sendMessage(content: string, options?: SendMessageOptions) {
    const state = this.store.getState();
    const activeId = state.activeConversationId;

    if (state.activeStreamId) {
      this.abortStream(state.activeStreamId);
    }

    const sessionId = generateSessionId();
    this.store.setState({ activeStreamId: sessionId });

    const controller = new AbortController();
    this.streamControllers.set(sessionId, controller);

    // ... stream logic
  }

  stopGeneration() {
    const { activeStreamId } = this.store.getState();
    if (activeStreamId) this.abortStream(activeStreamId);
  }

  private abortStream(sessionId: string) {
    this.streamControllers.get(sessionId)?.abort();
    this.streamControllers.delete(sessionId);
    this.store.setState({ activeStreamId: null });
  }
}

export const createChatService = (store = useChatStore) => new ChatService(store);
export const chatService = createChatService();
```

## Stream 处理关键逻辑（目标）

### PendingReferences
- `reference` event -> `pendingReferences`
- `message_end` -> 合并到 `references` + 清空 pending
- `error/abort` -> 清空 pending

### Rollback（错误恢复）
- 每次乐观更新写入 `pendingUpdates`，发生 parse 错误时回滚。

