## 类型定义汇总（目标）
```typescript
// ==================== 类型定义 ====================

type ConversationId = number;
type MessageId = string;
type SessionId = string;

interface ChatMessage {
  id: MessageId;
  conversationId: ConversationId;
  role: 'user' | 'assistant' | 'system';
  content: string;
  createdAt: number;
  metadata?: {
    todoList?: AgentTodoList;
    references?: AgentReferenceMap;
    followups?: string[];
  };
}

interface AgentTodoItem {
  id: string;
  content: string;
  status: 'pending' | 'in_progress' | 'completed' | 'failed';
  result?: string;
}

interface AgentTodoList {
  id: string;
  status: 'pending' | 'in_progress' | 'completed';
  items: AgentTodoItem[];
}

interface AgentReference {
  id: string;
  type: 'document' | 'chart' | 'table' | 'code';
  title: string;
  data: Record<string, unknown>;
}

type AgentReferenceMap = Record<string, AgentReference>;

type FollowupSource =
  | { type: 'ai_generated'; messageId: MessageId }
  | { type: 'client_inferred'; messageId: MessageId };

interface ChatError {
  code: string;
  message: string;
  recoverable: boolean;
  context?: {
    conversationId?: ConversationId;
    messageId?: MessageId;
  };
}

interface PendingUpdate {
  type: 'message' | 'todo' | 'reference';
  inverse: () => void;
}

interface ConversationState {
  messages: ChatMessage[];
  todoList: AgentTodoList | null;
  references: AgentReferenceMap;
  pendingReferences: AgentReferenceMap;
  followups: string[];
  followupSource: FollowupSource | null;

  isLoading: boolean;
  error: ChatError | null;

  finalMessageId?: string;
  lastAccessedAt: number;
  isStreaming: boolean;
  isPinned: boolean;

  pendingUpdates: PendingUpdate[];
}

interface SendMessageOptions {
  sessionId?: string;
  attachments?: File[];
  context?: Record<string, unknown>;
}

interface ChatStore {
  activeConversationId: ConversationId | undefined;
  activeStreamId: SessionId | null;
  conversations: Record<ConversationId, ConversationState>;
  conversationIds: ConversationId[];

  setActiveConversation: (id: ConversationId | undefined) => void;
  sendMessage: (content: string, options?: SendMessageOptions) => Promise<void>;
  stopGeneration: () => void;
  submitQuestionAnswer: (requestId: string, answers: Record<string, string>) => Promise<void>;
  clearConversation: (id: ConversationId) => void;
}
```

